// The light half of every built-in stage that has its road data loaded on demand: what the hub, the schedule,
// the stage lists and the leaderboards read before (or without) the stage's road arriving. GENERATED: do not edit.
// Regenerate with `UPDATE_STAGE_CATALOGUE=1 npx vitest run tests/unit/stageCatalogue.test.ts` after changing a
// stage's name, length, climbing, or segments; the same test fails if this file is out of step with the stages.

import type { Stage } from './stages';

/** Everything on a Stage the app reads without its road: the rest (`HEAVY_STAGE_FIELDS`) loads with it. */
export type StageInfo = Omit<Stage, 'elevationAt' | 'headingAt' | 'scenery' | 'landmarks' | 'signs' | 'race' | 'crowdSpots' | 'world'> & {
  world?: Omit<NonNullable<Stage['world']>, 'lapStage'>;
};

export interface CatalogueEntry {
  info: StageInfo;
  /** Total climbing in metres, as hub/data.ts stageClimb() sums it (over the first 20 km if endless). */
  climbM: number;
  /** The elevation profile in metres, PROFILE_SAMPLES evenly spaced points from 0 to the stage's length (20 km if endless): the hub's thumbnails. */
  profile: number[];
  /** The names of the stage's KOM segments, in order: the hub's KOM chip. */
  segments: string[];
}

/** Points in each stored profile. */
export const PROFILE_SAMPLES = 96;

